USE `acore_world`;

-- ============================================================================
-- World BoE drop rate increase
--
-- Source of truth: data/sql/base/db_world/reference_loot_template.sql
-- Functional goal: multiply by 5 the drop chance of Vanilla/TBC/WotLK world
--   BoE green/blue/purple reference entries, capped at 100 per row.
--
-- This file is deterministic and idempotent: running it once or ten times
-- produces exactly the same state because it sets absolute target values
-- derived from the pristine base chances, not from the current DB value.
-- It also repairs a DB where the previous multiplicative script was applied
-- more than once (e.g. values inflated to 25x).
--
-- IMPORTANT: the embedded base-chance snapshot is pinned to the current
-- AzerothCore base dump. If upstream/base reference_loot_template values
-- change, regenerate this file from the pristine base dump so the snapshot
-- does not become stale.
-- ============================================================================

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS `_boe_base_chances`;

CREATE TEMPORARY TABLE `_boe_base_chances` (
    `Entry`      INT UNSIGNED NOT NULL,
    `Item`       INT UNSIGNED NOT NULL,
    `BaseChance` FLOAT        NOT NULL,
    PRIMARY KEY (`Entry`, `Item`)
) ENGINE=InnoDB;


UPDATE `reference_loot_template` AS r
JOIN `_boe_base_chances` AS b
    ON b.`Entry` = r.`Entry` AND b.`Item` = r.`Item`
SET r.`Chance` = LEAST(b.`BaseChance` * 5.0, 100)
WHERE r.`Reference` <> 0
  AND r.`Comment` REGEXP '^(Vanilla|TBC|WotLK) (Greens|Blues|Purples) ';

DROP TEMPORARY TABLE IF EXISTS `_boe_base_chances`;

COMMIT;

